// Auto-generated embedded fallback data URIs for instant zero-dependency image rendering on live domains
export const WORKSHOP_EMBEDDED_FALLBACKS: Record<string, string> = {
  "/workshops/macrame_desk.jpeg": "data:image/jpeg;base64,",
  "macrame_desk.jpeg": "data:image/jpeg;base64,",
  "/workshops/macrame_group.jpeg": "data:image/jpeg;base64,",
  "macrame_group.jpeg": "data:image/jpeg;base64,",
  "/workshops/macrame_student.jpeg": "data:image/jpeg;base64,",
  "macrame_student.jpeg": "data:image/jpeg;base64,",
  "/workshops/macrame_snap.jpeg": "data:image/jpeg;base64,",
  "macrame_snap.jpeg": "data:image/jpeg;base64,",
  "/workshops/macrame_snap_thumb.jpg": "data:image/jpeg;base64,",
  "macrame_snap_thumb.jpg": "data:image/jpeg;base64,",
  "/workshops/macrame_cloud_thumb.jpg": "data:image/jpeg;base64,",
  "macrame_cloud_thumb.jpg": "data:image/jpeg;base64,",
  "/workshops/macrame_me_teaching_thumb.jpg": "data:image/jpeg;base64,",
  "macrame_me_teaching_thumb.jpg": "data:image/jpeg;base64,",
  "/workshops/macrame_pot_thumb.jpg": "data:image/jpeg;base64,",
  "macrame_pot_thumb.jpg": "data:image/jpeg;base64,"
};

export function getWorkshopEmbeddedFallback(url?: string): string | null {
  if (!url) return null;
  const cleanUrl = url.split("?")[0];
  if (WORKSHOP_EMBEDDED_FALLBACKS[cleanUrl]) {
    return WORKSHOP_EMBEDDED_FALLBACKS[cleanUrl];
  }
  const filename = cleanUrl.replace(/^.*\//, "");
  if (WORKSHOP_EMBEDDED_FALLBACKS[filename]) {
    return WORKSHOP_EMBEDDED_FALLBACKS[filename];
  }
  return null;
}
